from google.adk.agents.llm_agent import Agent

RATES_PER_METRE = {"m": 1.0, "km": 1000.0, "ft": 0.3048, "mi": 1609.344}


def convert_length(value: float, from_unit: str, to_unit: str) -> dict:
    """Converts a length between m, km, ft and mi.

    Args:
        value: the number to convert.
        from_unit: unit of the input, one of m, km, ft, mi.
        to_unit: unit wanted, one of m, km, ft, mi.
    """
    if from_unit not in RATES_PER_METRE or to_unit not in RATES_PER_METRE:
        return {"status": "error", "message": f"unknown unit: {from_unit} or {to_unit}"}
    metres = value * RATES_PER_METRE[from_unit]
    result = metres / RATES_PER_METRE[to_unit]
    return {"status": "success", "value": round(result, 4), "unit": to_unit}


CITIES = {"paris": {"country": "France", "timezone": "Europe/Paris"},
          "tokyo": {"country": "Japan", "timezone": "Asia/Tokyo"}}


def lookup_city(name: str) -> dict:
    """Returns the country and time zone of a city, or an error if unknown."""
    row = CITIES.get(name.strip().lower())
    if row is None:
        return {"status": "error", "message": f"no record for {name}"}
    return {"status": "success", "city": name, **row}


root_agent = Agent(
    model="gemini-flash-latest",
    name="root_agent",
    description="Converts lengths and looks up cities.",
    instruction=(
        "Answer with the tools. Use convert_length for unit questions and "
        "lookup_city for city questions. If a tool returns status error, "
        "say so and do not guess."
    ),
    tools=[convert_length, lookup_city],
)

